#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]
use soe_esm::{Entry,FileHeader,GlobalFormId,Group,GroupKind,LoadOrder,Plugin,Record,Tag};use soe_game::Game;
fn id(n:u32)->GlobalFormId{GlobalFormId{file:0,object:n}}
#[test]
fn dlg_02_in_combat_actor_does_not_auto_greet_on_entry(){
 let mut p=Plugin::new(FileHeader::default());for(f,n)in[(7,"Player"),(0x500,"Greeter")]{p.push_top(Record::new(Tag(*b"NPC_"),f).zsub(Tag(*b"EDID"),n).sub(Tag(*b"ACBS"),vec![0;24]));}let mut pos=vec![0;24];pos[..4].copy_from_slice(&20f32.to_le_bytes());p.push_top(Record::new(Tag(*b"ACHR"),0x100).sub(Tag(*b"NAME"),0x500u32.to_le_bytes()).sub(Tag(*b"DATA"),pos));p.push_top(Record::new(Tag(*b"QUST"),0x800).sub(Tag(*b"DNAM"),vec![0;12]).sub(Tag(*b"NEXT"),[]).sub(Tag(*b"INDX"),[0;4]));p.push_top(Record::new(Tag(*b"DLBR"),0x1900).sub(Tag(*b"QNAM"),0x800u32.to_le_bytes()).sub(Tag(*b"TNAM"),0u32.to_le_bytes()).sub(Tag(*b"DNAM"),1u32.to_le_bytes()).sub(Tag(*b"SNAM"),0x900u32.to_le_bytes()));let t=Record::new(Tag(*b"DIAL"),0x900).zsub(Tag(*b"FULL"),"Hello").sub(Tag(*b"QNAM"),0x800u32.to_le_bytes()).sub(Tag(*b"BNAM"),0x1900u32.to_le_bytes()).sub(Tag(*b"DATA"),[0,0,1,0]).sub(Tag(*b"SNAM"),*b"PFGT").sub(Tag(*b"PNAM"),50f32.to_le_bytes());let mut root=Group::new(GroupKind::Top(Tag(*b"DIAL")));root.entries.push(Entry::Record(p.push_record(t)));let mut child=Group::new(GroupKind::TopicChildren(0x900));let mut resp=vec![0;24];resp[12]=1;child.entries.push(Entry::Record(p.push_record(Record::new(Tag(*b"INFO"),0xA00).sub(Tag(*b"ENAM"),[0;4]).sub(Tag(*b"TRDT"),resp).zsub(Tag(*b"NAM1"),"Hello"))));root.entries.push(Entry::Group(child));p.groups.push(root);let mut lo=LoadOrder::new();lo.add("Greeting.esm",p).unwrap();let mut g=Game::new(lo);g.player();g.world_mut().drive_actor(id(0x100));g.start_quest(id(0x800));g.world_mut().actor(id(0x100)).unwrap().in_combat=true;g.tick(0.016);assert!(g.world().dialogue_session().is_none());
}
